package com.crms.entity;import com.crms.enums.JobStatus;import java.time.Instant;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;@Document("jobs") public class JobPosting{@Id private Long id;private Company company;private String title;private String description;private String location,jobType;private Double minCgpa;private Integer graduationYear,maxBacklogs;private JobStatus status=JobStatus.DRAFT;private Instant createdAt=Instant.now();public Long getId(){return id;}public void setId(Long v){id=v;}public Company getCompany(){return company;}public void setCompany(Company v){company=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getLocation(){return location;}public void setLocation(String v){location=v;}public String getJobType(){return jobType;}public void setJobType(String v){jobType=v;}public Double getMinCgpa(){return minCgpa;}public void setMinCgpa(Double v){minCgpa=v;}public Integer getGraduationYear(){return graduationYear;}public void setGraduationYear(Integer v){graduationYear=v;}public Integer getMaxBacklogs(){return maxBacklogs;}public void setMaxBacklogs(Integer v){maxBacklogs=v;}public JobStatus getStatus(){return status;}public void setStatus(JobStatus v){status=v;}public Instant getCreatedAt(){return createdAt;}}
